/* Тренировка «Распределённые данные»: CAP и PACELC, реплика с задержкой и «чтение своих записей», распределённая
   транзакция — 2PC против саги с компенсациями, outbox, выбор хранилища, миграция схемы без простоя.
   Кейс: у «Кадра» появились отдельные сервисы оплаты и бонусов, касса в Калининграде и реплика базы для отчётов.
   Ключ преподавателя — _dev/KEY.md, раздел «Распределённые данные». */
'use strict';
(function () {
  const TR = window.TR, ui = TR.ui, esc = TR.esc;
  const ID = 'dist';

  document.head.insertAdjacentHTML('beforeend', `<style>
  .ds-nodes{display:grid;grid-template-columns:minmax(0,1fr) 110px minmax(0,1fr);gap:8px;align-items:center}
  @media (max-width:640px){.ds-nodes{grid-template-columns:minmax(0,1fr)}}
  .ds-node{border:1px solid var(--border-strong);border-radius:12px;padding:10px 12px;background:var(--surface-2);display:grid;gap:6px;min-width:0}
  .ds-node b{font:700 14px var(--f-brand)}.ds-node small{color:var(--text-muted)}
  .ds-node.down{opacity:.55;border-style:dashed}
  .ds-link{text-align:center;font:600 12px var(--f-mono)}
  .ds-link .ln{height:4px;border-radius:2px;background:var(--ok);margin:6px 0}
  .ds-link.cut .ln{background:repeating-linear-gradient(90deg,var(--bad) 0 8px,transparent 8px 14px)}
  .ds-log{display:grid;gap:4px;max-height:220px;overflow:auto}
  .ds-log div{font-size:12.5px;padding:5px 9px;border-radius:8px;background:var(--surface-2);border-left:3px solid var(--border-strong)}
  .ds-log div.ok{border-left-color:var(--ok)}.ds-log div.bad{border-left-color:var(--bad);background:var(--bad-soft)}.ds-log div.warn{border-left-color:var(--warn)}
  .ds-seat{display:inline-block;font:600 12px/26px var(--f-mono);min-width:56px;text-align:center;border-radius:7px 7px 3px 3px;border:1px solid var(--border-strong);background:var(--surface)}
  .ds-seat.sold{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
  .ds-time{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,150px),1fr));gap:8px}
  .ds-time div{border:1px solid var(--border);border-radius:10px;padding:8px 10px;background:var(--surface);font-size:12.5px}
  .ds-time div.bad{border-color:var(--bad);background:var(--bad-soft)}.ds-time div.ok{border-color:var(--ok);background:var(--ok-soft)}
  .ds-time b{display:block;font:700 12px var(--f-mono);color:var(--text-muted)}
  </style>`);

  // =====================================================================
  // Схема 1. CAP: разрыв связи между центром и кассой в Калининграде
  const capViz = (el, opts) => {
    const o = opts || {};
    let mode = o.mode || 'CP', link = o.link != null ? o.link : false, log = [], kgd = 'free', ekb = 'free';
    const reset = () => { log = []; kgd = 'free'; ekb = 'free'; };
    const sale = where => {
      const mine = where === 'kgd' ? kgd : ekb;
      if (mine === 'sold') { log.push(['warn', `${where === 'kgd' ? 'Касса Калининграда' : 'Сайт (центр)'}: место 412 уже продано — отказ.`]); return; }
      if (link) { kgd = ekb = 'sold'; log.push(['ok', `${where === 'kgd' ? 'Касса Калининграда' : 'Сайт'} продал место 412. Связь есть — оба узла сразу знают, что место занято.`]); return; }
      if (mode === 'CP' && where === 'kgd') { log.push(['bad', 'Касса Калининграда: «Нет связи с центром — продажа временно невозможна». Покупатель уходит без билета. Зато двойной продажи не будет: выбрали <b>согласованность</b>.']); return; }
      if (where === 'kgd') { kgd = 'sold'; log.push(['warn', 'Касса Калининграда продала 412 по своей копии данных — центр об этом не знает. Выбрали <b>доступность</b>.']); }
      else { ekb = 'sold'; log.push(['warn', 'Сайт (центр) продал 412 — Калининград об этом не знает.']); }
      if (kgd === 'sold' && ekb === 'sold') log.push(['bad', '<b>Одно место продано дважды.</b> Узнаем, когда связь вернётся. Нужна сверка и компенсация: одному покупателю — другое место или возврат.']);
    };
    const draw = () => {
      el.innerHTML = `<div class="stack">
        <div class="row">${ui.seg('cap', [{ v: 'CP', t: 'CP — при разрыве отказываем' }, { v: 'AP', t: 'AP — при разрыве продаём' }], mode)}<button type="button" class="btn sm ${link ? 'danger' : ''}" data-cap="link">${link ? '✂ Оборвать связь' : '🔌 Восстановить связь'}</button></div>
        <div class="ds-nodes"><div class="ds-node"><b>Центр, Екатеринбург</b><small>основная база + сайт</small><div>Место 412: <span class="ds-seat ${ekb === 'sold' ? 'sold' : ''}">${ekb === 'sold' ? 'продано' : 'свободно'}</span></div></div>
          <div class="ds-link ${link ? '' : 'cut'}"><div class="ln"></div>${link ? 'связь есть' : 'РАЗРЫВ (P)'}</div>
          <div class="ds-node ${!link && mode === 'CP' ? 'down' : ''}"><b>Касса, Калининград</b><small>${!link && mode === 'CP' ? 'не продаёт без центра' : 'своя копия данных'}</small><div>Место 412: <span class="ds-seat ${kgd === 'sold' ? 'sold' : ''}">${kgd === 'sold' ? 'продано' : 'свободно'}</span></div></div></div>
        <div class="row"><button type="button" class="btn sm primary" data-cap="kgd">Касса Калининграда продаёт 412</button><button type="button" class="btn sm primary" data-cap="ekb">Сайт продаёт 412</button><button type="button" class="btn sm ghost" data-cap="reset">⟲ Сначала</button></div>
        <div class="ds-log">${log.length ? log.map(([k, t]) => `<div class="${k}">${t}</div>`).join('') : '<div>Нажмите «оборвать связь», затем продайте место с обеих сторон — в режиме CP и в режиме AP.</div>'}</div>
        <div class="qp-note"><b>CAP:</b> при разрыве сети (P) распределённая система выбирает одно из двух — <b>согласованность</b> (C: все видят одно и то же, но часть узлов отказывает) или <b>доступность</b> (A: отвечают все, но данные могут разойтись). Без разрыва выбирать не нужно — поэтому есть PACELC: «а в обычном режиме — задержка или согласованность?»</div></div>`;
    };
    ui.onSeg(el, (n, v) => { if (n !== 'cap') return; mode = v; reset(); draw(); o.onUse && o.onUse(); });
    TR.on(el, 'click', '[data-cap]', (e, b) => { const a = b.dataset.cap; if (a === 'link') { link = !link; if (link && kgd !== ekb) log.push(['warn', 'Связь вернулась: узлы обмениваются данными, расхождение обнаружено.']); } else if (a === 'reset') reset(); else sale(a); draw(); o.onUse && o.onUse(); });
    draw();
  };

  // Схема 2. Реплика с задержкой
  const replViz = (el, opts) => {
    const o = opts || {};
    let lag = o.lag != null ? o.lag : 2, fix = !!o.fix;
    const draw = () => {
      const readAt = 0.5, stale = !fix && lag > readAt, rep = lag <= 1.5 ? 'видит' : 'не видит';
      el.innerHTML = `<div class="stack">
        <label class="field"><span>Задержка реплики: <b class="tnum">${lag.toFixed(1)} с</b> (в пик бывает и 5–10 с)</span><input type="range" min="0" max="5" step="0.5" value="${lag}" data-lag></label>
        <label class="toggle"><input type="checkbox" data-fix ${fix ? 'checked' : ''}> <span>Включить «чтение своих записей»: 10 секунд после покупки читать заказы этого покупателя с основной базы</span></label>
        <div class="ds-time">
          <div><b>0,0 с · основная база</b>Покупатель оплатил: билет записан в основную базу.</div>
          <div class="${lag <= readAt || fix ? 'ok' : ''}"><b>${lag.toFixed(1)} с · реплика</b>Изменение доехало до реплики.</div>
          <div class="${stale ? 'bad' : 'ok'}"><b>0,5 с · экран «Мои билеты»</b>${fix ? 'Читаем с основной базы — билет на месте.' : stale ? 'Читаем с реплики — <b>билета нет</b>. Покупатель пишет в поддержку «деньги списали, билета нет» и покупает второй.' : 'Реплика успела — билет виден.'}</div>
          <div class="${lag <= 3 ? 'ok' : ''}"><b>отчёт Бориса Ильича</b>С реплики: цифры отстают на ${lag.toFixed(1)} с — ${rep === 'видит' || lag <= 3 ? 'для отчёта за неделю это не важно' : 'для недельного отчёта всё равно не важно'}.</div></div>
        <div class="qp-note"><b>Реплика</b> — копия базы, куда изменения доезжают с задержкой (асинхронная репликация). Её используют, чтобы разгрузить основную базу: отчёты, каталог. Но сразу после записи пользователь может «не увидеть себя». Лечат <b>чтением своих записей</b> (read-your-writes): свои свежие данные — с основной базы или с реплики, которая уже догнала нужную позицию журнала. Это и есть PACELC «в обычном режиме»: быстрее с реплики (L) или точнее с основной (C).</div></div>`;
    };
    el.addEventListener('input', e => { if (e.target.matches('[data-lag]')) { lag = +e.target.value; draw(); o.onUse && o.onUse(); } });
    el.addEventListener('change', e => { if (e.target.matches('[data-fix]')) { fix = e.target.checked; draw(); o.onUse && o.onUse(); } });
    draw();
  };

  // Схема 3. 2PC и сага
  const L3 = [{ id: 'coord', t: 'Заказы (координатор)' }, { id: 'pay', t: 'Оплата' }, { id: 'bonus', t: 'Бонусы' }];
  const FLOWS = {
    '2pc-ok': [{ from: 'coord', to: 'pay', t: 'PREPARE: готов списать 1 400?' }, { from: 'coord', to: 'bonus', t: 'PREPARE: готов начислить 70?' }, { from: 'pay', to: 'coord', t: 'готов (держу блокировку)', reply: true }, { from: 'bonus', to: 'coord', t: 'готов (держу блокировку)', reply: true }, { from: 'coord', to: 'pay', t: 'COMMIT', kind: 'ok' }, { from: 'coord', to: 'bonus', t: 'COMMIT', kind: 'ok', note: 'Двухфазный коммит: сначала все обещают «готов», потом координатор говорит всем «фиксируй». Атомарно для всех участников.' }],
    '2pc-no': [{ from: 'coord', to: 'pay', t: 'PREPARE' }, { from: 'coord', to: 'bonus', t: 'PREPARE' }, { from: 'pay', to: 'coord', t: 'готов', reply: true }, { from: 'bonus', to: 'coord', t: 'не готов: сервис перегружен', reply: true, kind: 'bad' }, { from: 'coord', to: 'pay', t: 'ROLLBACK', kind: 'warn' }, { from: 'coord', to: 'bonus', t: 'ROLLBACK', kind: 'warn', note: 'Один участник сказал «нет» — откатываются все. Это атомарность на несколько систем.' }],
    '2pc-crash': [{ from: 'coord', to: 'pay', t: 'PREPARE' }, { from: 'coord', to: 'bonus', t: 'PREPARE' }, { from: 'pay', to: 'coord', t: 'готов (держу блокировку)', reply: true }, { from: 'bonus', to: 'coord', t: 'готов (держу блокировку)', reply: true }, { from: 'coord', to: 'coord', t: 'координатор упал', kind: 'bad' }, { from: 'pay', to: 'pay', t: 'жду… строки заблокированы', kind: 'warn' }, { from: 'bonus', to: 'bonus', t: 'жду… строки заблокированы', kind: 'warn', note: 'Главная беда 2PC: участники пообещали и ждут решения, держа блокировки. Пока координатор не поднимется, они не могут ни зафиксировать, ни откатить. А банк и внешние сервисы в 2PC вообще не участвуют — поэтому между микросервисами чаще используют сагу.' }],
    'saga-ok': [{ from: 'coord', to: 'coord', t: 'T1: забронировать места (своя транзакция)', kind: 'ok' }, { from: 'coord', to: 'pay', t: 'T2: списать 1 400' }, { from: 'pay', to: 'coord', t: 'списано (зафиксировано)', reply: true, kind: 'ok' }, { from: 'coord', to: 'bonus', t: 'T3: начислить 70 баллов' }, { from: 'bonus', to: 'coord', t: 'начислено', reply: true, kind: 'ok' }, { from: 'coord', to: 'coord', t: 'T4: заказ оплачен', kind: 'ok', note: 'Сага — цепочка локальных транзакций: каждый сервис фиксирует свой шаг сразу. Блокировок между сервисами нет.' }],
    'saga-fail': [{ from: 'coord', to: 'coord', t: 'T1: забронировать места', kind: 'ok' }, { from: 'coord', to: 'pay', t: 'T2: списать 1 400' }, { from: 'pay', to: 'coord', t: 'списано', reply: true, kind: 'ok' }, { from: 'coord', to: 'bonus', t: 'T3: начислить баллы' }, { from: 'bonus', to: 'coord', t: 'ошибка: аккаунт заблокирован', reply: true, kind: 'bad' }, { from: 'coord', to: 'pay', t: 'C2: вернуть 1 400 (компенсация)', kind: 'warn' }, { from: 'coord', to: 'coord', t: 'C1: снять бронь мест', kind: 'warn' }, { from: 'coord', to: 'coord', t: 'заказ отменён', note: 'Шаг упал — откатить зафиксированное нельзя, поэтому выполняют <b>компенсации</b> в обратном порядке: вернуть деньги, снять бронь. Между шагами система видна в промежуточном состоянии — это цена саги (согласованность в конечном счёте).' }]
  };
  const sagaViz = (el, start) => {
    let v = start || '2pc-ok';
    el.innerHTML = `<div class="stack">${ui.seg('fl', [{ v: '2pc-ok', t: '2PC: все готовы' }, { v: '2pc-no', t: '2PC: один не готов' }, { v: '2pc-crash', t: '2PC: координатор упал' }, { v: 'saga-ok', t: 'Сага: успех' }, { v: 'saga-fail', t: 'Сага: сбой и компенсации' }], v)}<div data-sq></div></div>`;
    const sq = ui.seq(TR.$('[data-sq]', el), { lanes: L3, steps: FLOWS[v], speed: 1100, laneW: 210 });
    ui.onSeg(el, (n, x) => { if (n !== 'fl') return; v = x; sq.set(FLOWS[x], { play: true }); });
    return sq;
  };

  // Схема 4. Outbox
  const L4 = [{ id: 'app', t: 'Сервис заказов' }, { id: 'db', t: 'Его база' }, { id: 'br', t: 'Брокер' }, { id: 'bon', t: 'Бонусы' }];
  const OB = {
    dual: [{ from: 'app', to: 'db', t: 'COMMIT: билет продан', kind: 'ok' }, { from: 'app', to: 'br', t: 'отправить «билет продан»', lost: true, kind: 'bad' }, { from: 'app', to: 'app', t: 'сбой / брокер недоступен', kind: 'bad', note: 'Двойная запись: в базу записали, а событие не ушло. Бонусы никогда не узнают о продаже — баллы не начислены. Наоборот (сначала событие, потом база упала) — бонусы начислят за непроданный билет.' }],
    outbox: [{ from: 'app', to: 'db', t: 'BEGIN: билет + строка в outbox', note: 'В одной транзакции: и сам билет, и запись события в таблицу outbox той же базы.' }, { from: 'app', to: 'db', t: 'COMMIT', kind: 'ok', note: 'Либо и билет, и событие, либо ничего — атомарность локальной транзакции.' }, { from: 'db', to: 'br', t: 'ретранслятор читает outbox, публикует' }, { from: 'br', to: 'db', t: 'брокер недоступен → повтор позже', reply: true, kind: 'warn', note: 'Если брокер лежит, событие не теряется — оно в outbox, ретранслятор повторит.' }, { from: 'db', to: 'br', t: 'повтор: опубликовано', kind: 'ok' }, { from: 'br', to: 'bon', t: '«билет продан» (может прийти дважды)' }, { from: 'bon', to: 'bon', t: 'уже обработано? event_id → пропустить', kind: 'ok', note: 'Повторы возможны (доставка «хотя бы один раз»), поэтому получатель идемпотентен: помнит обработанные event_id.' }]
  };
  const outboxViz = (el, start) => {
    let v = start || 'dual';
    el.innerHTML = `<div class="stack">${ui.seg('ob', [{ v: 'dual', t: 'Двойная запись: база + брокер' }, { v: 'outbox', t: 'Outbox' }], v)}<div data-sq></div></div>`;
    const sq = ui.seq(TR.$('[data-sq]', el), { lanes: L4, steps: OB[v], speed: 1100, laneW: 170 });
    ui.onSeg(el, (n, x) => { if (n !== 'ob') return; v = x; sq.set(OB[x], { play: true }); });
  };

  // =====================================================================
  // Теория 1. CAP и PACELC
  const howCap = {
    id: 'how-cap', title: 'Как это работает: CAP — что делать, когда сеть порвалась', covers: ['cap'], free: true, noReset: true,
    simple: { icon: '🌐', plain: 'Когда данные живут на нескольких узлах, связь между ними может пропасть. В этот момент система выбирает: <b>отказать</b>, чтобы данные не разошлись (согласованность, C), или <b>отвечать</b> по своей копии, рискуя расхождением (доступность, A). Одновременно и то и другое при разрыве (P) невозможно — это теорема CAP.', analogy: 'Две кассы продают билеты по общему списку. Телефон между ними сломался. Либо одна закрывается, пока не дозвонится (C), либо обе продают и вечером разбираются с двойными продажами (A).', tech: 'CAP (Э. Брюер): Consistency, Availability, Partition tolerance — при разделении сети выбирают C или A. PACELC (Д. Абади): при разделении (P) — A или C, иначе (E) — задержка (L) или согласованность (C).' },
    lead: ui.brief({ situation: 'Касса в Калининграде работает по копии данных центра. Вечером пропала связь.', todo: ['Оборвите связь и продайте место 412 с обеих сторон в режиме CP, затем в режиме AP.', 'Восстановите связь и посмотрите, что обнаружится.'], look: 'В каком режиме покупатель уходит без билета, а в каком двое получают одно место.' }),
    render(el, ctx) { capViz(el, { onUse: () => { ctx.ans.n = (ctx.ans.n || 0) + 1; ctx.save(); if (ctx.ans.n >= 4) ctx.ready(); } }); if (ctx.readonly || (ctx.ans.n || 0) >= 4) ctx.ready(); }
  };

  // Практика 1. CP или AP
  const CAPR = [
    { id: 'c1', t: 'Продажа мест на сеанс', ok: 'cp', because: 'Двойная продажа хуже, чем временный отказ: при разрыве касса не продаёт без подтверждения центра.' },
    { id: 'c2', t: 'Списание баллов при оплате', ok: 'cp', because: 'Баллы — деньги. Потратить одни и те же баллы дважды на двух узлах нельзя.' },
    { id: 'c3', t: 'Афиша и расписание на сайте', ok: 'ap', because: 'Лучше показать расписание пятиминутной давности, чем «сайт недоступен». Расписание меняется редко.' },
    { id: 'c4', t: 'Счётчик «сколько человек смотрят эту страницу»', ok: 'ap', because: 'Неточное число никому не вредит, а отказ — вредит. Сверка потом не нужна.' },
    { id: 'c5', t: 'Лента «популярное за неделю»', ok: 'ap', because: 'Рейтинг за неделю не меняется от одной продажи: показываем по своей копии.' },
    { id: 'c6', t: 'Возврат денег за билет', ok: 'cp', because: 'Вернуть деньги дважды — прямой убыток. При разрыве возврат ждёт связи.' }
  ];
  const cap = TR.task.match({
    id: 'cap', title: 'CP или AP: что делать при разрыве для каждой функции',
    lead: ui.brief({ situation: 'Нина Сергеевна: «Если у Калининграда пропадёт связь — касса должна работать или нет?» Артём: «Ответ разный для разных функций».', todo: ['Для каждой функции выберите поведение при разрыве сети.', 'Нажмите «Проверить».'], look: 'Спросите: что хуже для бизнеса — временный отказ или расхождение данных, которое потом придётся разбирать?' }),
    rows: CAPR.map(r => ({ id: r.id, t: esc(r.t), ok: r.ok, because: r.because, slip: { cp: 'отказ здесь вредит больше, чем возможное расхождение', ap: 'расхождение здесь — деньги или двойная продажа' } })),
    choices: [{ v: 'cp', t: 'CP — отказать, пока нет связи' }, { v: 'ap', t: 'AP — отвечать по своей копии, сверить потом' }], placeholder: 'При разрыве…',
    viz(el, ans) { el.innerHTML = `<div class="stack">${ui.table(['Функция', 'Вы', 'Верно', 'Почему'], CAPR.map(r => { const g = (ans.m || {})[r.id]; return [esc(r.t), g ? `<span style="color:var(--${g === r.ok ? 'ok' : 'bad'})">${g.toUpperCase()}</span>` : '—', `<b>${r.ok.toUpperCase()}</b>`, r.because]; }))}<div class="dv-k">Проиграйте продажу места при разрыве</div><div data-c></div></div>`; capViz(TR.$('[data-c]', el)); },
    explain: '<p>CAP выбирают не для системы целиком, а для каждой операции: деньги и места — CP (лучше отказать), витрины и счётчики — AP (лучше ответить устаревшим). Аналитик записывает это в нефункциональные требования: «при недоступности центра касса не продаёт» — это и есть решение по CAP.</p>'
  });

  // =====================================================================
  // Теория 2. Реплика
  const howRepl = {
    id: 'how-repl', title: 'Как это работает: реплика, задержка и «чтение своих записей»', covers: ['repl'], free: true, noReset: true,
    simple: { icon: '🪞', plain: 'Реплика — копия базы на другом сервере. Изменения доезжают до неё не мгновенно, а с задержкой. С реплики удобно читать отчёты и каталог, но сразу после записи можно прочитать старые данные — например, не увидеть только что купленный билет.', analogy: 'Объявление повесили в центральном офисе, а копию в филиал везёт курьер. Тот, кто сразу побежал в филиал, объявления ещё не увидит.', tech: 'Асинхронная репликация: lag. Синхронная — без задержки, но запись ждёт реплику. Read-your-writes, monotonic reads — гарантии для пользователя. PACELC: в обычном режиме выбирают задержку (L) или согласованность (C).' },
    lead: ui.brief({ situation: 'Экран «Мои билеты» читает данные с реплики, чтобы не нагружать основную базу.', todo: ['Двигайте задержку и смотрите, видит ли покупатель билет через полсекунды.', 'Включите «чтение своих записей».'], look: 'При какой задержке появляется проблема и что её снимает.' }),
    render(el, ctx) { replViz(el, { onUse: () => { ctx.ans.n = (ctx.ans.n || 0) + 1; ctx.save(); if (ctx.ans.n >= 2) ctx.ready(); } }); if (ctx.readonly || (ctx.ans.n || 0) >= 2) ctx.ready(); }
  };
  const repl = TR.task.quizSet({
    id: 'repl', title: '«Деньги списали, а билета нет»',
    lead: ui.brief({ situation: 'После переноса чтения на реплику поддержка получает жалобы: покупатель оплатил, открыл «Мои билеты» — пусто. Через несколько секунд билет появляется. Часть покупателей успевает купить второй.', todo: ['Ответьте на три вопроса.', 'Нажмите «Проверить».'], look: 'Лаборатория «Реплика, задержка и чтение своих записей».' }),
    qs: [
      { id: 'q1', q: 'В чём причина?', options: [
        { t: 'Экран читает с реплики, а изменение доезжает до неё с задержкой', ok: true, why: 'Да.', because: 'Асинхронная реплика отстаёт: запись уже в основной базе, а реплика её ещё не получила.' },
        { t: 'Билет не записался, а потом записался повторно', why: 'Билет записан один раз — в основную базу. Пусто только на реплике.' },
        { t: 'Ошибка уникального индекса', why: 'Индекс ни при чём: строка есть, её просто ещё нет на реплике.' }
      ], viz: el => replViz(el, { lag: 2 }) },
      { id: 'q2', q: 'Какие решения снимают проблему? (несколько)', options: [
        { t: 'Свои свежие данные читать с основной базы (например, 10 секунд после записи)', ok: true, why: 'Да.', because: 'Это «чтение своих записей»: пользователь всегда видит то, что сам только что сделал.' },
        { t: 'Читать с реплики, только если она уже догнала позицию журнала этой записи', ok: true, why: 'Да.', because: 'Тот же принцип, точнее: приложение запоминает позицию записи и ждёт реплику, которая её прошла.' },
        { t: 'После оплаты показывать данные из ответа сервиса, не перечитывая', ok: true, why: 'Да.', because: 'Экран успеха строят из того, что вернула операция оплаты, — реплика не нужна.' },
        { t: 'Убрать реплику совсем', why: 'Работает, но выбрасывает разгрузку основной базы: отчёты и каталог снова ложатся на неё.' }
      ], viz: el => replViz(el, { lag: 2, fix: true }) },
      { id: 'q3', q: 'Отчёт Бориса Ильича о выручке за неделю — можно ли считать по реплике?', options: [
        { t: 'Да: отставание на секунды не меняет недельную цифру, а основная база разгружается', ok: true, why: 'Да.', because: 'Это PACELC в обычном режиме: для отчёта выбираем задержку ради скорости, для экрана покупателя — согласованность.' },
        { t: 'Нет: отчёты только с основной базы', why: 'Тяжёлые отчёты на основной базе тормозят продажи. Для них реплика и нужна.' }
      ] }
    ],
    viz: el => replViz(el, { lag: 3 }),
    explain: '<p>Реплика разгружает основную базу, но отстаёт. Требование, которое пишет аналитик: «пользователь видит свои изменения сразу» (read-your-writes), а отчёты допускают задержку N секунд. Это и есть PACELC без сбоя: где важнее скорость, а где — точность.</p>'
  });

  // =====================================================================
  // Схема 5. Схемы репликации: ведущий–ведомые, несколько ведущих, кворум, шардирование
  const topoViz = (el, opts) => {
    const o = opts || {};
    let mode = o.mode || 'ls';
    // ведущий–ведомые
    let L = { nodes: [{ n: 'Ведущий (master)', w: [] }, { n: 'Ведомый 1 (replica)', w: [] }, { n: 'Ведомый 2 (replica)', w: [] }], lead: 0, sync: false, next: 1, lost: [], log: [] };
    // несколько ведущих
    let M = { ekb: 450, kgd: 450, rule: 'lww', changed: [], log: [] };
    // кворум
    let Q = { W: 2, R: 2 };
    let H = { q: 'one' };
    const chip = (w, cls) => `<span class="ds-seat ${cls || ''}" style="min-width:auto;padding:0 8px">${esc(w)}</span>`;
    const lsWrite = () => { const id = 'продажа ' + L.next++; L.nodes[L.lead].w.push(id); if (L.sync) L.nodes.forEach((x, i) => { if (i !== L.lead && !x.down) x.w.push(id); }); L.log.push(['ok', `${id}: записана на ведущем${L.sync ? ' и сразу на ведомых (синхронно — запись ждала их подтверждения)' : '; ведомые получат её с задержкой'}.`]); };
    const lsCatch = () => { const src = L.nodes[L.lead].w; L.nodes.forEach((x, i) => { if (i !== L.lead && !x.down) x.w = src.slice(); }); L.log.push(['ok', 'Репликация: ведомые догнали ведущего.']); };
    const lsFail = () => {
      const old = L.nodes[L.lead]; old.down = true;
      const cand = L.nodes.findIndex((x, i) => i !== L.lead && !x.down); if (cand < 0) return;
      const lost = old.w.filter(w => !L.nodes[cand].w.includes(w));
      L.lead = cand; L.nodes[cand].n = 'Ведомый → новый ведущий'; L.lost = lost;
      L.log.push(['bad', `Ведущий упал. Ведомый повышен до ведущего (failover).${lost.length ? ` <b>Потеряно: ${lost.join(', ')}</b> — они были только на старом ведущем и не успели доехать. Покупатель видел «оплачено», а заказа нет.` : ' Ничего не потеряно: всё успело доехать.'}`]);
    };
    function body() {
      if (mode === 'ls') return `<div class="row"><label class="toggle"><input type="checkbox" data-sync ${L.sync ? 'checked' : ''}> <span>Синхронная репликация (запись ждёт ведомых)</span></label></div>
        <div class="ds-time">${L.nodes.map((x, i) => `<div class="${x.down ? 'bad' : i === L.lead ? 'ok' : ''}"><b>${esc(x.n)}${x.down ? ' — упал' : i === L.lead ? ' · пишет' : ' · только читает'}</b>${x.w.map(w => chip(w, L.lost.includes(w) ? 'sold' : '')).join(' ') || '<span class="dim">пусто</span>'}</div>`).join('')}</div>
        <div class="row"><button type="button" class="btn sm primary" data-tp="w">Записать продажу</button><button type="button" class="btn sm" data-tp="c">Реплики догнали</button><button type="button" class="btn sm danger" data-tp="f" ${L.nodes.filter(x => !x.down).length < 2 ? 'disabled' : ''}>Ведущий упал</button><button type="button" class="btn sm ghost" data-tp="r">⟲ Сначала</button></div>
        <div class="ds-log">${L.log.length ? L.log.map(([k, t]) => `<div class="${k}">${t}</div>`).join('') : '<div>Запишите 2–3 продажи, нажмите «Реплики догнали», запишите ещё одну и уроните ведущего. Повторите с синхронной репликацией.</div>'}</div>
        <div class="qp-note"><b>Ведущий–ведомые (master–slave, leader–follower)</b>: все записи идут на одного ведущего, ведомые получают копию и обслуживают чтение. Просто и без конфликтов. Риски: при <b>асинхронной</b> репликации падение ведущего теряет последние записи; при <b>синхронной</b> запись ждёт ведомого и тормозит. Компромисс — полусинхронная: ждём хотя бы одного ведомого.</div>`;
      if (mode === 'mm') return `<div class="row">${ui.seg('mmr', [{ v: 'lww', t: 'Конфликт: «последняя запись побеждает»' }, { v: 'own', t: 'Каждый узел правит только свои данные' }], M.rule)}</div>
        <div class="ds-nodes"><div class="ds-node"><b>Ведущий, Екатеринбург</b><small>Нина Сергеевна</small><div>Цена сеанса Калининграда: <b>${M.ekb} ₽</b></div></div><div class="ds-link"><div class="ln"></div>обмен изменениями</div><div class="ds-node"><b>Ведущий, Калининград</b><small>менеджер кинотеатра</small><div>Цена сеанса Калининграда: <b>${M.kgd} ₽</b></div></div></div>
        <div class="row"><button type="button" class="btn sm primary" data-tp="e">Екатеринбург: цена 500</button><button type="button" class="btn sm primary" data-tp="k">Калининград: цена 400</button><button type="button" class="btn sm" data-tp="s">Обменяться изменениями</button><button type="button" class="btn sm ghost" data-tp="r">⟲ Сначала</button></div>
        <div class="ds-log">${M.log.length ? M.log.map(([k, t]) => `<div class="${k}">${t}</div>`).join('') : '<div>Измените цену в обоих городах, потом нажмите «Обменяться». Сравните два правила.</div>'}</div>
        <div class="qp-note"><b>Несколько ведущих (master–master)</b>: писать можно в любом узле — удобно для удалённых городов, работает и при разрыве. Цена — <b>конфликты</b>: одно и то же изменили в двух местах. «Последняя запись побеждает» молча теряет одно изменение. Надёжнее разделить владение: данные кинотеатра правит только его узел.</div>`;
      if (mode === 'q') { const ok = Q.W + Q.R > 3; return `<div class="row"><label class="field" style="flex:1 1 180px"><span>W — сколько узлов подтверждают запись: <b>${Q.W}</b></span><input type="range" min="1" max="3" value="${Q.W}" data-q="W"></label><label class="field" style="flex:1 1 180px"><span>R — со скольких узлов читаем: <b>${Q.R}</b></span><input type="range" min="1" max="3" value="${Q.R}" data-q="R"></label></div>
        <div class="ds-time">${[0, 1, 2].map(i => { const wrote = i < Q.W, read = i >= 3 - Q.R; return `<div class="${wrote && read ? 'ok' : read ? 'bad' : ''}"><b>Узел ${i + 1}</b>${wrote ? chip('цена 500 (новая)') : chip('цена 450 (старая)')}<br><span class="small">${read ? 'читаем отсюда' : ''}</span></div>`; }).join('')}</div>
        <div class="nl-res ${ok ? '' : 'bad'}" style="padding:10px 14px;border-radius:12px;border-left:4px solid var(--${ok ? 'ok' : 'bad'});background:var(--${ok ? 'ok' : 'bad'}-soft)">N = 3, W = ${Q.W}, R = ${Q.R}: W + R = ${Q.W + Q.R} ${ok ? '&gt; N — читаемые и записанные узлы обязательно пересекаются: свежая цена будет прочитана.' : '≤ N — можно прочитать только старые узлы и не увидеть свежую запись.'}</div>
        <div class="qp-note"><b>Без ведущего (кворум, как в Cassandra и DynamoDB)</b>: запись отправляют на все N узлов и ждут W подтверждений, чтение — с R узлов. Если <b>W + R &gt; N</b>, хоть один прочитанный узел точно видел запись. Меньше W и R — быстрее и доступнее, но можно прочитать старое.</div>`; }
      const SH = { one: ['Выручка «Кадр Янтарь» за неделю', [2], 'Один шард: запрос идёт на сервер Калининграда — быстро.'], all: ['Выручка всей сети', [0, 1, 2], 'Все шарды: запрос уходит на три сервера, результаты складывают — медленнее и сложнее.'], move: ['Покупатель переехал из Перми в Калининград: перенести его заказы', [1, 2], 'Транзакция через два шарда — одной BEGIN…COMMIT нет, нужна сага или 2PC.'] };
      const s = SH[H.q];
      return `<div class="row">${ui.seg('shq', Object.entries(SH).map(([v, x]) => ({ v, t: x[0] })), H.q)}</div>
        <div class="ds-time">${['Шард 1: Екатеринбург', 'Шард 2: Пермь', 'Шард 3: Калининград'].map((t, i) => `<div class="${s[1].includes(i) ? (H.q === 'move' ? 'bad' : 'ok') : ''}"><b>${t}</b>кинотеатр, сеансы, билеты, заказы своего города</div>`).join('')}</div>
        <div class="qp-note">${s[2]} <b>Шардирование</b> — разделение данных по серверам по ключу (здесь — город). Каждый сервер держит свою часть и свою нагрузку. Ключ выбирают так, чтобы частые запросы попадали в один шард; запросы и транзакции через несколько шардов дороги. Репликация копирует данные целиком, шардирование — делит их.</div>`;
    }
    function draw() { el.innerHTML = `<div class="stack">${ui.seg('topo', [{ v: 'ls', t: 'Ведущий–ведомые' }, { v: 'mm', t: 'Несколько ведущих' }, { v: 'q', t: 'Кворум без ведущего' }, { v: 'sh', t: 'Шардирование' }], mode)}${body()}</div>`; }
    ui.onSeg(el, (n, v) => { if (n === 'topo') mode = v; if (n === 'mmr') { M.rule = v; M = { ekb: 450, kgd: 450, rule: v, changed: [], log: [] }; } if (n === 'shq') H.q = v; draw(); o.onUse && o.onUse(); });
    el.addEventListener('change', e => { if (e.target.matches('[data-sync]')) { L.sync = e.target.checked; draw(); o.onUse && o.onUse(); } });
    el.addEventListener('input', e => { const q = e.target.dataset && e.target.dataset.q; if (q) { Q[q] = +e.target.value; draw(); o.onUse && o.onUse(); } });
    TR.on(el, 'click', '[data-tp]', (e, b) => {
      const a = b.dataset.tp;
      if (a === 'w') lsWrite(); if (a === 'c') lsCatch(); if (a === 'f') lsFail();
      if (a === 'r') { if (mode === 'ls') L = { nodes: [{ n: 'Ведущий (master)', w: [] }, { n: 'Ведомый 1 (replica)', w: [] }, { n: 'Ведомый 2 (replica)', w: [] }], lead: 0, sync: L.sync, next: 1, lost: [], log: [] }; else M = { ekb: 450, kgd: 450, rule: M.rule, changed: [], log: [] }; }
      if (a === 'e') { M.ekb = 500; M.changed.push('ekb'); M.log.push(['warn', 'Екатеринбург поставил 500 ₽ (в 10:00:01).']); }
      if (a === 'k') { M.kgd = 400; M.changed.push('kgd'); M.log.push(['warn', 'Калининград поставил 400 ₽ (в 10:00:02).']); }
      if (a === 's') {
        const both = M.changed.includes('ekb') && M.changed.includes('kgd');
        if (M.rule === 'own') { M.ekb = M.kgd = M.changed.includes('kgd') ? 400 : 450; M.log.push([both ? 'ok' : 'ok', both ? 'Цены сеансов Калининграда правит только узел Калининграда: изменение Екатеринбурга отклонено сразу с понятной ошибкой. Конфликта нет.' : 'Обмен прошёл без конфликтов.']); }
        else if (both) { M.ekb = M.kgd = 400; M.log.push(['bad', '<b>Конфликт.</b> Правило «последняя запись побеждает» оставило 400 ₽ (она на секунду позже). Изменение Нины Сергеевны молча пропало — она об этом не узнает.']); }
        else { const v = M.changed.includes('ekb') ? 500 : M.changed.includes('kgd') ? 400 : 450; M.ekb = M.kgd = v; M.log.push(['ok', 'Изменение было в одном узле — оно доехало до второго.']); }
        M.changed = [];
      }
      draw(); o.onUse && o.onUse();
    });
    draw();
  };
  const howTopo = {
    id: 'how-topo', title: 'Как это работает: схемы репликации — ведущий–ведомые, несколько ведущих, кворум, шардирование', covers: ['topo'], free: true, noReset: true,
    simple: { icon: '🧬', plain: 'Реплицировать — значит держать копии данных на нескольких серверах. Схемы разные: <b>один ведущий</b> принимает записи, ведомые копируют (master–slave); <b>несколько ведущих</b> принимают записи каждый у себя (master–master); <b>без ведущего</b> — запись и чтение кворумом. Отдельно от этого — <b>шардирование</b>: данные не копируют, а делят между серверами.', analogy: 'Ведущий–ведомые: один бухгалтер ведёт книгу, остальные переписывают копии. Несколько ведущих: два бухгалтера ведут книгу каждый у себя и вечером сверяются. Шардирование: у каждого филиала своя книга.', tech: 'Leader-follower (PostgreSQL streaming, MySQL), multi-leader (BDR, Galera, офлайн-клиенты), leaderless (Dynamo-стиль: Cassandra, Riak; N, W, R), sharding (по диапазону, по хэшу). Failover, split brain, полусинхронная репликация.' },
    lead: ui.brief({ situation: 'Четыре способа разнести данные «Кадра» по серверам.', todo: ['Пройдите все четыре режима: запишите продажи и уроните ведущего; поменяйте цену в двух городах; подвигайте W и R; выберите запросы для шардов.'], look: 'Где теряются данные, где возникают конфликты и от чего зависит, увидит ли чтение свежую запись.' }),
    render(el, ctx) { topoViz(el, { onUse: () => { ctx.ans.n = (ctx.ans.n || 0) + 1; ctx.save(); if (ctx.ans.n >= 6) ctx.ready(); } }); if (ctx.readonly || (ctx.ans.n || 0) >= 6) ctx.ready(); }
  };
  const topo = TR.task.quizSet({
    id: 'topo', title: 'Репликация в «Кадре»: ведущий упал, конфликт цен, кворум',
    lead: ui.brief({ situation: 'Артём собрал пять ситуаций из реальных систем, похожих на «Кадр». В каждой нужно понять, что произойдёт с данными и что записать в требования.', todo: ['Ответьте на пять вопросов.', 'Нажмите «Проверить». К каждому ответу — схема в нужном режиме.'], look: 'Лаборатория «Схемы репликации».' }),
    qs: [
      { id: 'p1', q: 'Ведущий (master) с асинхронной репликацией упал, ведомого повысили. Что с продажами последней секунды?', options: [
        { t: 'Те, что не успели доехать до ведомого, потеряны — хотя покупатели видели «оплачено»', ok: true, why: 'Да.', because: 'При асинхронной репликации подтверждение получено от ведущего до копирования. Если он упал, а новый ведущий — ведомый, который отставал, последние записи пропадают.' },
        { t: 'Ничего не теряется: ведомый — точная копия', why: 'Точная — только с задержкой. Всё, что не успело доехать, теряется.' },
        { t: 'Продажи переедут на новый ведущий при перезапуске старого', why: 'Обычно старый ведущий после возвращения становится ведомым и его «лишние» записи отбрасываются — иначе будут противоречия.' }
      ], viz: el => topoViz(el, { mode: 'ls' }) },
      { id: 'p2', q: 'Как не терять оплаченные заказы при падении ведущего?', options: [
        { t: 'Синхронная или полусинхронная репликация для заказов и платежей: подтверждение — после записи хотя бы на одном ведомом', ok: true, why: 'Да.', because: 'Тогда «оплачено» значит «есть минимум на двух серверах». Плата — запись медленнее на время ответа ведомого.' },
        { t: 'Добавить больше ведомых', why: 'При асинхронной репликации все они могут отставать одинаково.' },
        { t: 'Делать резервную копию раз в сутки', why: 'Потеряете до суток продаж.' }
      ], viz: el => topoViz(el, { mode: 'ls' }) },
      { id: 'p3', q: 'После разрыва сети каждая половина кластера выбрала своего ведущего. Как это называется и чем опасно?', options: [
        { t: 'Split brain: два ведущих принимают записи, данные расходятся; защищаются голосованием большинства и «ограждением» старого ведущего', ok: true, why: 'Да.', because: 'Ведущий должен избираться большинством узлов (кворум), а старый — гарантированно отключаться от записи (fencing). Иначе обе половины продают одни и те же места.' },
        { t: 'Шардирование — нормальная работа', why: 'Шардирование делит данные намеренно; здесь два ведущих для одних и тех же данных.' },
        { t: 'Failover — ничего страшного', why: 'Failover — смена ведущего. Два ведущих одновременно — авария.' }
      ], viz: el => capViz(el, { mode: 'AP' }) },
      { id: 'p4', q: 'Схема «несколько ведущих»: Екатеринбург поставил цену сеанса 500, Калининград в ту же минуту — 400. Правило «последняя запись побеждает». Что получится?', options: [
        { t: 'Останется одна цена, второе изменение молча пропадёт; надёжнее — данные кинотеатра правит только его узел', ok: true, why: 'Да.', because: 'Конфликты записи — главная цена схемы с несколькими ведущими. «Последняя побеждает» их не решает, а прячет. Разделение владения убирает конфликт.' },
        { t: 'База сохранит обе цены', why: 'В одной ячейке одно значение — одна цена проиграет.' },
        { t: 'Запись в одном из городов будет отклонена автоматически', why: 'При «последняя побеждает» обе записи принимаются, а потом одна затирается.' }
      ], viz: el => topoViz(el, { mode: 'mm' }) },
      { id: 'p5', q: 'Кворум без ведущего: N = 3. Какие настройки гарантируют, что чтение увидит последнюю запись?', options: [
        { t: 'W = 2, R = 2', ok: true, why: 'Да: 2 + 2 > 3.', because: 'Если W + R > N, множества записанных и прочитанных узлов пересекаются — хотя бы один прочитанный узел видел запись.' },
        { t: 'W = 3, R = 1', ok: true, why: 'Да: 3 + 1 > 3.', because: 'Запись на все три узла — любое чтение с одного увидит её. Но запись упадёт, если недоступен хотя бы один узел.' },
        { t: 'W = 1, R = 1', why: '1 + 1 ≤ 3: можно записать на один узел, а прочитать с другого.' },
        { t: 'W = 1, R = 2', why: '1 + 2 = 3, не больше N: пересечения может не быть.' }
      ], viz: el => topoViz(el, { mode: 'q' }) }
    ],
    viz: el => topoViz(el),
    explain: '<p>Ведущий–ведомые — стандарт для реляционных баз: просто и без конфликтов, но при асинхронной репликации падение ведущего теряет последние записи (лечат полусинхронной репликацией для важных данных) и есть риск split brain (лечат выбором большинством). Несколько ведущих — для удалённых узлов и офлайна, ценой конфликтов. Кворум — правило W + R &gt; N. Шардирование делит данные, а не копирует, и делает дорогими запросы через шарды.</p>'
  });

  // =====================================================================
  // Теория 3. Распределённая транзакция
  const howSaga = {
    id: 'how-saga', title: 'Как это работает: транзакция через несколько сервисов — 2PC и сага', covers: ['tx2', 'saga'], free: true, noReset: true,
    simple: { icon: '🔗', plain: 'Когда заказ, оплата и бонусы — разные сервисы со своими базами, одной транзакции BEGIN…COMMIT на всех нет. Есть два подхода. <b>Двухфазный коммит (2PC)</b>: координатор спрашивает всех «готовы?», потом говорит «фиксируйте» — атомарно, но все ждут координатора и держат блокировки. <b>Сага</b>: каждый сервис фиксирует свой шаг сразу, а при сбое выполняются <b>компенсации</b> — обратные действия в обратном порядке.', analogy: '2PC — нотариус собирает подписи всех сторон и только потом заверяет сделку. Сага — каждый делает свою часть сразу, а если сделка сорвалась, каждый отменяет своё: вернуть деньги, снять бронь.', tech: '2PC (XA): prepare/commit, блокирующий протокол, требует участия всех ресурсов. Сага (Гарсиа-Молина, 1987): оркестрация или хореография, компенсирующие транзакции, согласованность в конечном счёте.' },
    lead: ui.brief({ situation: 'Покупка теперь проходит через три сервиса: заказы, оплата, бонусы.', todo: ['Проиграйте все пять сценариев.'], look: 'Что происходит с блокировками, когда падает координатор 2PC, и в каком порядке идут компенсации в саге.' }),
    render(el, ctx) { sagaViz(el); el.addEventListener('click', e => { if (e.target.closest('[data-seg] button,[data-sq]')) { ctx.ans.n = (ctx.ans.n || 0) + 1; ctx.save(); if (ctx.ans.n >= 4) ctx.ready(); } }); if (ctx.readonly || (ctx.ans.n || 0) >= 4) ctx.ready(); }
  };
  const tx2 = TR.task.quizSet({
    id: 'tx2', title: '2PC или сага для покупки через три сервиса',
    lead: ui.brief({ situation: 'Подрядчик предлагает: «Сделаем распределённую транзакцию через 2PC — заказы, оплата и бонусы зафиксируются атомарно». Оплата идёт через внешний банк.', todo: ['Ответьте на три вопроса.', 'Нажмите «Проверить».'], look: 'Кто может участвовать в 2PC и что случится, если координатор упадёт между фазами.' }),
    qs: [
      { id: 't1', q: 'Главная проблема 2PC в этой схеме?', options: [
        { t: 'Если координатор упал после PREPARE, участники держат блокировки и не могут решить сами; а внешний банк в 2PC не участвует вовсе', ok: true, why: 'Да.', because: '2PC блокирующий: «готов» — это обещание, которое нельзя забрать без решения координатора. И все участники должны поддерживать протокол — банк этого не делает.' },
        { t: '2PC не атомарен', why: 'Атомарен — в этом его смысл. Проблема в блокировках и требованиях к участникам.' },
        { t: '2PC работает только в одной базе', why: 'Наоборот, он для нескольких ресурсов. Но все они должны поддерживать протокол.' }
      ], viz: el => sagaViz(el, '2pc-crash') },
      { id: 't2', q: 'Что такое компенсация в саге?', options: [
        { t: 'Обратное действие для уже зафиксированного шага: вернуть деньги, снять бронь', ok: true, why: 'Да.', because: 'Зафиксированный шаг откатить нельзя — его отменяют новым действием, которое восстанавливает смысл (не обязательно исходное состояние байт в байт).' },
        { t: 'ROLLBACK всех сервисов одновременно', why: 'В саге каждый шаг уже зафиксирован — ROLLBACK невозможен.' },
        { t: 'Повтор упавшего шага', why: 'Повтор — тоже приём, но компенсация — это отмена предыдущих шагов.' }
      ], viz: el => sagaViz(el, 'saga-fail') },
      { id: 't3', q: 'Что придётся принять, выбрав сагу?', options: [
        { t: 'Промежуточные состояния видны: деньги уже списаны, а заказ ещё не подтверждён — нужны статусы и идемпотентные шаги', ok: true, why: 'Да.', because: 'Согласованность в конечном счёте: между шагами система не «целая». Отсюда требования: статусы заказа (оплачивается, отменяется), повторяемые без вреда шаги и компенсации.' },
        { t: 'Ничего — сага во всём лучше 2PC', why: 'Сага снимает блокировки, но отдаёт промежуточную видимость и сложность компенсаций.' },
        { t: 'Отказ от транзакций в каждом сервисе', why: 'Наоборот: каждый шаг саги — локальная транзакция своего сервиса.' }
      ], viz: el => sagaViz(el, 'saga-ok') }
    ],
    viz: el => sagaViz(el, '2pc-crash'),
    explain: '<p>2PC даёт атомарность на несколько ресурсов ценой блокировок и требований к участникам — внешние API в нём не участвуют. Между микросервисами чаще выбирают сагу: локальные транзакции плюс компенсации, статусы для промежуточных состояний и идемпотентные шаги. Это решение аналитик фиксирует в постановке: какие шаги, какие компенсации, какие статусы видит пользователь.</p>'
  });

  // Практика 3. Порядок саги с компенсациями
  const SG = [
    { id: 's1', t: 'T1: забронировать места 412 и 413' }, { id: 's2', t: 'T2: списать 1 400 ₽ через банк' }, { id: 's3', t: 'T3: начислить баллы — ошибка, аккаунт заблокирован' },
    { id: 's4', t: 'C2: вернуть 1 400 ₽ (компенсация оплаты)' }, { id: 's5', t: 'C1: снять бронь мест (компенсация брони)' }, { id: 's6', t: 'Заказ → статус «отменён», покупателю — сообщение' }
  ];
  const SG_WHY = { s1: 'Сначала то, что легче всего отменить и что защищает от двойной продажи: бронь.', s2: 'Деньги списывают, когда место уже держим.', s3: 'Третий шаг падает — дальше идти нельзя.', s4: 'Компенсации — в обратном порядке: последнее зафиксированное отменяем первым. Деньги вернуть важнее всего.', s5: 'Затем снимаем бронь — место снова продаётся.', s6: 'И только после компенсаций — итоговый статус и сообщение покупателю.' };
  const saga = {
    id: 'saga', title: 'Соберите сагу покупки со сбоем и компенсациями',
    lead: ui.brief({ situation: 'Артём: «Сага — это не только шаги, но и порядок отмены. Начисление баллов упало. Расставь всё, что произойдёт, по порядку».', todo: ['Расставьте шесть шагов в порядке выполнения.', 'Нажмите «Проверить».'], look: 'Компенсации выполняются в обратном порядке шагов: последнее сделанное отменяется первым.' }),
    blank: () => ({ o: TR.shuffle(SG.map(x => x.id), 'saga-kadr') }),
    reference: () => ({ o: SG.map(x => x.id) }),
    render(el, ctx) { const a = ctx.ans; if (!a.o || a.o.length !== SG.length) a.o = TR.shuffle(SG.map(x => x.id), 'saga-kadr'); const rv = ctx.result || ctx.readonly ? Object.fromEntries(a.o.map((id, i) => [id, SG[i].id === id ? 'ok' : 'bad'])) : null; ui.order(el, { items: SG, value: a.o, reveal: rv, readonly: ctx.readonly, onChange: v => { a.o = v; ctx.save(); } }); },
    check(ans) { const s = ui.orderScore(ans.o || [], SG.map(x => x.id)); const o = ans.o || [], notes = []; if (o.indexOf('s5') < o.indexOf('s4') && o.indexOf('s4') > -1) notes.push({ ok: false, html: 'Компенсации — в обратном порядке шагов: сначала отменяем оплату (последний удачный шаг), потом бронь.' }); if (o.indexOf('s6') < o.indexOf('s4')) notes.push({ ok: false, html: 'Статус «отменён» — после компенсаций: иначе покупатель увидит «отменён», а деньги ещё не вернулись.' }); return { ok: s === 1, score: s, notes, summary: `На своём месте ${o.filter((id, i) => SG[i].id === id).length} из ${SG.length}.` }; },
    answers: ans => SG.map((x, i) => ({ q: `Шаг ${i + 1}`, mine: ((SG.find(y => y.id === (ans.o || [])[i]) || {}).t) || '', right: x.t, ok: (ans.o || [])[i] === x.id, why: SG_WHY[x.id] })),
    viz: el => sagaViz(el, 'saga-fail'),
    explain: '<p>Шаги саги идут от легко отменяемого к трудно отменяемому (бронь → деньги → баллы), а компенсации — в обратном порядке. Итоговый статус — после компенсаций. Каждый шаг и каждая компенсация должны быть идемпотентными: координатор может повторить их после сбоя.</p>',
    report: ans => (ans.o || []).map(id => (SG.find(x => x.id === id) || {}).t).join(' → ')
  };

  // =====================================================================
  // Практика 4. Outbox
  const outbox = TR.task.quizSet({
    id: 'outbox', title: 'Событие «билет продан» потерялось',
    lead: ui.brief({ situation: 'Сервис заказов записывает билет в свою базу, а потом отправляет событие в брокер — его слушают бонусы. В понедельник брокер перезапускали, и за 3 минуты сотня покупателей осталась без баллов.', todo: ['Ответьте на три вопроса.', 'Нажмите «Проверить». В разборе — двойная запись и outbox по шагам.'], look: 'Можно ли записать в базу и в брокер атомарно?' }),
    qs: [
      { id: 'o1', q: 'Почему событие потерялось?', options: [
        { t: 'Это «двойная запись»: база и брокер — две системы, общей транзакции у них нет; база зафиксировала, а отправка не удалась', ok: true, why: 'Да.', because: 'Между COMMIT в базе и отправкой в брокер может случиться что угодно. Записать в обе системы атомарно без специального приёма нельзя.' },
        { t: 'Брокер удалил сообщение', why: 'Сообщение до брокера даже не дошло.' },
        { t: 'Бонусы не прочитали сообщение вовремя', why: 'Читать было нечего — событие не опубликовано.' }
      ], viz: el => outboxViz(el, 'dual') },
      { id: 'o2', q: 'Как устроен outbox? (несколько)', options: [
        { t: 'Билет и запись события пишутся в одной транзакции той же базы (таблица outbox)', ok: true, why: 'Да.', because: 'Локальная транзакция делает «билет + событие» атомарными.' },
        { t: 'Отдельный ретранслятор читает outbox и публикует в брокер, повторяя при сбоях', ok: true, why: 'Да.', because: 'Брокер недоступен — событие ждёт в таблице и уйдёт позже.' },
        { t: 'Отправленные записи помечаются или удаляются из outbox', ok: true, why: 'Да.', because: 'Чтобы не публиковать бесконечно; повтор при сбое между публикацией и пометкой всё равно возможен.' },
        { t: 'Событие отправляется в брокер до записи в базу', why: 'Тогда при сбое базы бонусы начислят за непроданный билет — та же двойная запись наоборот.' }
      ], viz: el => outboxViz(el, 'outbox') },
      { id: 'o3', q: 'Что обязательно на стороне бонусов?', options: [
        { t: 'Идемпотентность: обработанные event_id запоминаются, повтор пропускается', ok: true, why: 'Да.', because: 'Outbox гарантирует доставку «хотя бы один раз»: событие может прийти дважды. Без идемпотентности — двойные баллы.' },
        { t: 'Ничего — outbox гарантирует ровно одну доставку', why: 'Ровно одну он не гарантирует: сбой между публикацией и пометкой даст повтор.' },
        { t: 'Читать события только раз в сутки', why: 'Частота чтения не решает повторов.' }
      ] }
    ],
    viz: el => outboxViz(el, 'outbox'),
    explain: '<p>Нельзя атомарно записать в базу и в брокер — это «двойная запись». Outbox решает её локальной транзакцией: событие пишется рядом с данными, ретранслятор публикует его с повторами. Цена — возможные дубли, поэтому получатели идемпотентны (event_id). Подробно про брокеры — в практикуме «Неделя в «Минутке»».</p>'
  });

  // =====================================================================
  // Практика 5. Выбор хранилища
  const ST = [
    { id: 'h1', t: 'Продажи, места, заказы, платежи — строгие правила и транзакции', ok: 'rel', because: 'Связи, ограничения, ACID — сильная сторона реляционной базы.' },
    { id: 'h2', t: 'Бронь места и корзина на 15 минут, тысячи обращений в секунду', ok: 'kv', because: 'Короткоживущие данные с автоудалением по сроку (TTL) и очень быстрым доступом по ключу — хранилище «ключ-значение» (Redis). Но окончательная продажа — всё равно в реляционной базе.' },
    { id: 'h3', t: 'Карточки фильмов от разных дистрибьюторов: у каждого свой набор полей', ok: 'doc', because: 'Разная структура записей и чтение карточки целиком — документная база (или столбец JSONB в PostgreSQL).' },
    { id: 'h4', t: 'Аналитика продаж за 5 лет: миллиарды строк, суммы по любым срезам', ok: 'col', because: 'Колоночная аналитическая база (ClickHouse) читает только нужные столбцы и быстро считает агрегаты по огромным объёмам.' },
    { id: 'h5', t: 'Поиск фильма по описанию с опечатками: «глубна подводная»', ok: 'search', because: 'Полнотекстовый поиск с морфологией и нечётким совпадением — поисковый движок (Elasticsearch, OpenSearch).' },
    { id: 'h6', t: '«Смотревшие этот фильм смотрели и…» — связи между зрителями и фильмами в несколько шагов', ok: 'graph', because: 'Обход связей на несколько шагов — задача графовой базы (Neo4j). На небольших объёмах справится и реляционная.' }
  ];
  const STC = [{ v: 'rel', t: 'Реляционная (PostgreSQL)' }, { v: 'kv', t: 'Ключ-значение (Redis)' }, { v: 'doc', t: 'Документная (MongoDB, JSONB)' }, { v: 'col', t: 'Колоночная аналитическая (ClickHouse)' }, { v: 'search', t: 'Поисковая (Elasticsearch)' }, { v: 'graph', t: 'Графовая (Neo4j)' }];
  const store = TR.task.match({
    id: 'store', title: 'Какое хранилище под какую задачу',
    lead: ui.brief({ situation: 'Подрядчик: «Давайте всё положим в MongoDB, она быстрая». Артём: «Хранилище выбирают под задачу. Разложи шесть задач «Кадра»».', todo: ['Для каждой задачи выберите тип хранилища.', 'Нажмите «Проверить».'], look: 'Что важнее в задаче: транзакции и связи, скорость по ключу, гибкая структура, агрегаты по огромным объёмам, полнотекстовый поиск или обход связей?' }),
    rows: ST.map(r => ({ id: r.id, t: esc(r.t), ok: r.ok, because: r.because })),
    choices: STC, placeholder: 'Хранилище…',
    viz(el, ans) {
      el.innerHTML = `<div class="stack">${ui.table(['Тип', 'Сильная сторона', 'Слабая сторона', 'В «Кадре»', 'Вы'], [
        ['Реляционная', 'связи, ограничения, ACID, SQL', 'горизонтальное масштабирование сложнее', 'продажи, места', 'rel'], ['Ключ-значение', 'миллионы операций по ключу, TTL', 'нет запросов по содержимому', 'брони, сессии, кеш', 'kv'], ['Документная', 'гибкая структура, документ целиком', 'слабые связи между документами', 'карточки фильмов', 'doc'],
        ['Колоночная', 'агрегаты по миллиардам строк', 'медленные точечные изменения', 'аналитика за 5 лет', 'col'], ['Поисковая', 'полнотекст, опечатки, ранжирование', 'не источник правды', 'поиск по описанию', 'search'], ['Графовая', 'обход связей в несколько шагов', 'узкая специализация', 'рекомендации', 'graph']
      ].map(r => { const id = r[4], mine = ST.filter(s => (ans.m || {})[s.id] === id).map(s => ST.indexOf(s) + 1 + (s.ok === id ? '✓' : '✗')).join(', '); return [`<b>${r[0]}</b>`, r[1], r[2], r[3], mine || '—']; }))}<div class="qp-note">Последний столбец — номера задач, которые вы отнесли к этому типу. Типичная система — несколько хранилищ сразу (polyglot persistence), но <b>источник правды для денег и продаж — один</b>, с транзакциями. Остальные — копии для скорости и поиска, их наполняют событиями или выгрузками.</div></div>`;
    },
    explain: '<p>Реляционная база — источник правды там, где транзакции и связи. Ключ-значение — для коротких данных и кеша, документная — для гибких структур, колоночная — для аналитики, поисковая — для полнотекста, графовая — для связей в несколько шагов. «Всё в одной модной базе» почти всегда означает, что где-то потеряются транзакции или удобство запросов.</p>'
  });

  // =====================================================================
  // Практика 6. Миграция без простоя
  const MG = [
    { id: 'm1', t: 'Добавить столбец full_name (может быть пустым)', need: [], set: 'col', why: 'Новый необязательный столбец старой кассе не мешает — она его просто не видит.' },
    { id: 'm2', t: 'Новая версия приложения пишет имя в оба столбца', need: ['col'], set: 'dual', why: 'С этого момента новые строки заполнены в обоих столбцах.' },
    { id: 'm3', t: 'Перенести имена старых строк пачками в full_name', need: ['col', 'dual'], set: 'fill', why: 'Переносим, когда запись в оба уже идёт: иначе строки, созданные во время переноса, останутся без full_name. Пачками — чтобы не блокировать таблицу.' },
    { id: 'm4', t: 'Приложение читает только full_name', need: ['fill'], set: 'read', why: 'Читать новое можно, когда в нём есть все данные.' },
    { id: 'm5', t: 'Обновить кассы до новой версии (старая читала customer_name)', need: ['read'], set: 'kassa', why: 'Старая касса читает старый столбец — пока она жива, его нельзя ни бросать, ни удалять.' },
    { id: 'm6', t: 'Перестать писать в customer_name', need: ['kassa'], set: 'nowrite', why: 'Теперь старый столбец никто не читает.' },
    { id: 'm7', t: 'Удалить столбец customer_name', need: ['nowrite'], set: 'drop', why: 'Последний шаг — когда ни чтения, ни записи старого столбца не осталось.' }
  ];
  const MG_NEED = { col: 'столбца full_name ещё нет', dual: 'новые строки пишутся только в старый столбец — перенос пропустит их', fill: 'в full_name ещё нет данных старых строк — покупатели увидят пустые имена', read: 'приложение ещё читает старый столбец', kassa: 'старые кассы ещё читают customer_name', nowrite: 'в старый столбец ещё пишут' };
  const migrSim = order => { const have = new Set(); return order.map(id => { const s = MG.find(x => x.id === id); const miss = s.need.filter(n => !have.has(n)); have.add(s.set); return { s, miss }; }); };
  const migrViz = (el, order) => {
    const run = migrSim(order && order.length === MG.length ? order : MG.map(x => x.id));
    let k = run.findIndex(r => r.miss.length); if (k < 0) k = run.length - 1;
    const draw = () => {
      const have = new Set(run.slice(0, k + 1).map(r => r.s.set));
      const cols = ['id', have.has('drop') ? null : 'customer_name', have.has('col') ? 'full_name' : null].filter(Boolean);
      const rows = [[1, 'Анна Смирнова', have.has('fill') || have.has('dual') ? 'Анна Смирнова' : null], [62, 'Иван Попов', have.has('fill') ? 'Иван Попов' : null], [70, have.has('nowrite') ? null : 'Ольга Новикова', have.has('dual') ? 'Ольга Новикова' : null]].map(r => cols.map(c => c === 'id' ? r[0] : c === 'customer_name' ? r[1] : r[2]));
      const cur = run[k];
      el.innerHTML = `<div class="stack"><div class="small dim">Порядок — ваш. Нажимайте шаги: таблица показывает состояние после шага.</div>
        <ol class="tx-steps">${run.map((r, i) => `<li><button type="button" data-mg="${i}" aria-pressed="${i === k}" class="${i <= k ? 'past' : ''} ${i === k ? 'on' : ''} ${r.miss.length ? 'bad' : 'ok'}"><span class="n">${i + 1}</span><span>${esc(r.s.t)}${r.miss.length ? `<code style="color:var(--bad)">ломается: ${esc(r.miss.map(m => MG_NEED[m]).join('; '))}</code>` : ''}</span><small>${r.miss.length ? '✗' : '✓'}</small></button></li>`).join('')}</ol>
        ${ui.dbt({ name: 'customer после шага ' + (k + 1), cols, rows })}
        <div class="qp-note" ${cur.miss.length ? 'style="border-left-color:var(--bad)"' : ''}>${cur.miss.length ? `<b>На этом шаге система ломается:</b> ${esc(cur.miss.map(m => MG_NEED[m]).join('; '))}.` : esc(cur.s.why)}</div></div>`;
    };
    TR.on(el, 'click', '[data-mg]', (e, b) => { k = +b.dataset.mg; draw(); });
    draw();
  };
  const migr = {
    id: 'migr', title: 'Переименуйте поле, не остановив кассы',
    lead: ui.brief({ situation: 'Нужно переименовать customer.customer_name в full_name. Кассы в трёх городах обновляются по очереди за неделю, а останавливать продажи нельзя.', todo: ['Расставьте семь шагов миграции в безопасном порядке.', 'Нажмите «Проверить». В разборе — что ломается на каждом шаге при вашем порядке.'], look: 'Схема «расширить → перенести → переключить → сузить» (expand / contract): сначала добавляем новое, удаляем старое — последним.' }),
    blank: () => ({ o: TR.shuffle(MG.map(x => x.id), 'migr-kadr') }),
    reference: () => ({ o: MG.map(x => x.id) }),
    render(el, ctx) { const a = ctx.ans; if (!a.o || a.o.length !== MG.length) a.o = TR.shuffle(MG.map(x => x.id), 'migr-kadr'); const sim = migrSim(a.o); const rv = ctx.result || ctx.readonly ? Object.fromEntries(sim.map(r => [r.s.id, r.miss.length ? 'bad' : 'ok'])) : null; ui.order(el, { items: MG, value: a.o, reveal: rv, readonly: ctx.readonly, onChange: v => { a.o = v; ctx.save(); } }); },
    check(ans) { const sim = migrSim(ans.o || []), bad = sim.filter(r => r.miss.length); return { ok: !bad.length && (ans.o || []).length === MG.length, score: (MG.length - bad.length) / MG.length, notes: bad.slice(0, 3).map(r => ({ ok: false, html: `«${esc(r.s.t)}» — ${esc(r.miss.map(m => MG_NEED[m]).join('; '))}.` })), summary: bad.length ? `Шагов, на которых система ломается: ${bad.length}.` : 'Ни один шаг не ломает работающие кассы.' }; },
    answers: ans => { const sim = migrSim(ans.o || []); return MG.map((x, i) => ({ q: `Шаг ${i + 1}`, mine: ((MG.find(y => y.id === (ans.o || [])[i]) || {}).t) || '', right: x.t, ok: (ans.o || [])[i] === x.id, slip: sim[i] && sim[i].miss.length ? 'на этом месте ломается: ' + sim[i].miss.map(m => MG_NEED[m]).join('; ') : '', why: x.why })); },
    viz: (el, ans) => migrViz(el, ans.o),
    explain: '<p>Миграция без простоя — серия обратно совместимых шагов: <b>расширить</b> (добавить новое, не трогая старое), писать в оба, перенести данные, переключить чтение, дождаться, пока старых клиентов не останется, и только потом <b>сузить</b> — перестать писать и удалить старое. Ломающее изменение одной командой (RENAME COLUMN) сломает каждую кассу, которая ещё не обновлена.</p>',
    report: ans => (ans.o || []).map(id => (MG.find(x => x.id === id) || {}).t).join(' → ')
  };

  // =====================================================================
  TR.stage({
    id: ID, act: 3, order: 65, slot: 'Распределённые', title: 'Распределённые данные: CAP, реплики, саги, outbox',
    when: 'среда · «Кадр» растёт: отдельные сервисы оплаты и бонусов, касса в Калининграде, реплика для отчётов',
    intro: [
      { who: 'artem', html: 'Пока база была одна, транзакция решала всё. Теперь у нас сервисы оплаты и бонусов со своими базами, касса в Калининграде со своей копией и реплика для отчётов. Одного BEGIN…COMMIT на всех больше нет — разберёмся, что вместо него.' }
    ],
    glossary: [
      { term: 'Распределённая система', simple: 'Данные и обработка живут на нескольких серверах, связанных сетью.', tech: 'Узлы обмениваются сообщениями; сеть может терять, задерживать и разделять узлы.' },
      { term: 'CAP-теорема', simple: 'При разрыве сети система выбирает: согласованность (кто-то откажет) или доступность (данные могут разойтись).', tech: 'Consistency, Availability, Partition tolerance (Э. Брюер, 2000; доказана Гилбертом и Линч, 2002).' },
      { term: 'PACELC', simple: 'Дополнение к CAP: при разрыве — доступность или согласованность, а без разрыва — скорость или согласованность.', tech: 'If Partition — Availability or Consistency, Else — Latency or Consistency (Д. Абади, 2010).' },
      { term: 'Согласованность в конечном счёте', simple: 'Копии данных какое-то время расходятся, но со временем сходятся.', tech: 'Eventual consistency: при отсутствии новых изменений все реплики придут к одному состоянию.' },
      { term: 'Реплика', simple: 'Копия базы на другом сервере.', tech: 'Физическая или логическая репликация; синхронная (без задержки, медленнее запись) или асинхронная (с задержкой).' },
      { term: 'Задержка репликации', simple: 'Сколько времени изменение едет до реплики.', tech: 'Replication lag: разница позиций журнала основной базы и реплики.' },
      { term: 'Чтение своих записей', simple: 'Гарантия: пользователь всегда видит то, что сам только что изменил.', tech: 'Read-your-writes: чтение с основной базы или с реплики, догнавшей позицию записи.' },
      { term: 'Двухфазный коммит (2PC)', simple: 'Координатор спрашивает всех «готовы?», потом говорит всем «фиксируйте» или «откатывайте».', tech: 'Prepare/commit; блокирующий протокол; XA-транзакции. Все участники должны поддерживать протокол.' },
      { term: 'Сага', simple: 'Цепочка локальных транзакций разных сервисов; при сбое — компенсации в обратном порядке.', tech: 'Оркестрация (центральный координатор) или хореография (события); согласованность в конечном счёте.' },
      { term: 'Компенсация', simple: 'Обратное действие для уже сделанного шага: вернуть деньги, снять бронь.', tech: 'Компенсирующая транзакция; должна быть идемпотентной.' },
      { term: 'Двойная запись', simple: 'Запись в две системы (база и брокер) без общей транзакции: одна может пройти, другая — нет.', tech: 'Dual write problem; решается transactional outbox или CDC.' },
      { term: 'Outbox', simple: 'Таблица событий в той же базе: событие пишется в одной транзакции с данными, потом публикуется.', tech: 'Transactional outbox + ретранслятор (polling или CDC); доставка «хотя бы один раз».' },
      { term: 'Идемпотентность', simple: 'Повтор операции не меняет результат: второе начисление по тому же событию пропускается.', tech: 'Ключ идемпотентности / event_id, журнал обработанных сообщений.' },
      { term: 'Polyglot persistence', simple: 'Несколько разных хранилищ в одной системе — каждое под свою задачу.', tech: 'Реляционное, ключ-значение, документное, колоночное, поисковое, графовое.' },
      { term: 'Миграция без простоя', simple: 'Изменение схемы серией совместимых шагов: добавить новое, перенести, переключить, удалить старое.', tech: 'Expand / contract (parallel change); обратная совместимость со старыми клиентами на каждом шаге.' },
      { term: 'Ведущий–ведомые (master–slave)', simple: 'Все записи идут на один сервер-ведущий, остальные получают копию и обслуживают чтение.', tech: 'Leader–follower replication; PostgreSQL streaming replication, MySQL replication.' },
      { term: 'Несколько ведущих (master–master)', simple: 'Записи принимает каждый из нескольких серверов; изменения обмениваются, возможны конфликты.', tech: 'Multi-leader replication; разрешение конфликтов: last write wins, слияние, разделение владения.' },
      { term: 'Синхронная и полусинхронная репликация', simple: 'Синхронная: запись подтверждается после копирования на ведомые. Полусинхронная: ждём хотя бы одного ведомого.', tech: 'Synchronous / semi-synchronous replication: нет потери подтверждённых записей ценой задержки записи.' },
      { term: 'Failover', simple: 'Переключение на новый ведущий, когда старый упал.', tech: 'Повышение (promotion) ведомого; при асинхронной репликации возможна потеря неотреплицированных записей.' },
      { term: 'Split brain', simple: 'После разрыва сети два сервера одновременно считают себя ведущими и принимают записи.', tech: 'Лечится выбором ведущего большинством (кворум) и ограждением (fencing) старого ведущего.' },
      { term: 'Кворум (N, W, R)', simple: 'Запись подтверждают W из N узлов, читают с R узлов; если W + R > N, чтение увидит последнюю запись.', tech: 'Leaderless (Dynamo-стиль) репликация: Cassandra, Riak, DynamoDB.' },
      { term: 'Шардирование', simple: 'Разделение данных по нескольким серверам: например, кинотеатры по городам — на разных серверах.', tech: 'Горизонтальное секционирование по ключу шардирования; запросы между шардами дороги.' }
    ],
    outro: 'CAP — для каждой операции, реплики — с чтением своих записей, между сервисами — сага с компенсациями, события — через outbox, хранилище — под задачу, миграции — расширить и сузить. Осталось собрать всё перед собеседованием.',
    tasks: [howCap, cap, howRepl, repl, howTopo, topo, howSaga, tx2, saga, outbox, store, migr]
  });
})();
